{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/missingbulb/Claudinite/blob/main/packs/claudinite-tasks/task.schema.json",
  "title": "Claudinite task declaration",
  "description": "A tasks/<name>/task.json: what a scheduled task is, when it runs, and what its run does to pull requests. The runtime contract is packs/claudinite-tasks/task-contract.mjs; the enums here mirror its lists and a test holds them in step. Absent, preconditions is run-always, automerge is nothing and agent_model is none; the timeouts have no default.",
  "type": "object",
  "required": [
    "id",
    "description",
    "frequency",
    "expected_outcome"
  ],
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "The task's name — the same as its directory name."
    },
    "description": {
      "type": "string",
      "minLength": 1,
      "description": "What the task does, or why it exists, in at most fifty words — never what the other fields already say (the cadence, the conditions, the policy, the files)."
    },
    "frequency": {
      "type": "string",
      "enum": [
        "daily",
        "weekly",
        "monthly",
        "manual"
      ],
      "description": "The anchor the task is instantiated on. `manual` is woken by whatever knows the event happened."
    },
    "preconditions": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The conditions that must all hold for the task to run: built-in terms (e.g. \"substantive-change\", \"commits-under:<dir>\"), terms the task's own preconditions.mjs exports, `||` between alternatives. Optional: absent, the task runs always ([\"none\"])."
    },
    "expected_outcome": {
      "type": "string",
      "enum": [
        "no_code_changes",
        "fresh_pr",
        "amend_existing_or_create_new_pr",
        "supersede_existing_pr"
      ],
