# Publishes site/ to GitHub Pages on every push to main (no paths filter).
# Artifact-flow deploy (no gh-pages branch); the custom domain (claudinite.com)
# is configured in the repository's Pages settings, not here — see
# site/README.md. Uploading site/ (never the repo root) keeps the agent-tooling
# dirs out of the artifact.
name: Deploy site to GitHub Pages

on:
  push:
    branches: [main]
  workflow_dispatch:

permissions:
  # write: the release commits its version bump back to main
  contents: write
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: false

jobs:
  deploy:
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - uses: actions/checkout@v5

      # Every production release advances the version. package.json is the single
      # source of truth; the bumped files are committed back to main so the number
      # in the repo always names the last release that actually went out. The
      # script also stamps the site's footer tooltip from that same number —
      # see scripts/bump-version.mjs.
      - name: Bump version
        id: bump
        run: |
          NEW_VERSION=$(node scripts/bump-version.mjs)
          echo "version=$NEW_VERSION" >> "$GITHUB_OUTPUT"
          echo "Released version $NEW_VERSION"

      - name: Commit the version bump
        # [skip ci] keeps this commit from re-triggering this workflow, so there
        # is no deploy loop. Rebase-and-retry because the Claudinite scheduler and
        # its maintenance PRs also land on main, and a race here would otherwise
        # lose the bump and leave the repo claiming an older version than shipped.
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add package.json site/*.html
          git commit -m "Bump version to ${{ steps.bump.outputs.version }} [skip ci]"
          for attempt in 1 2 3 4 5; do
            if git push origin HEAD:main; then
              echo "Pushed the version bump on attempt $attempt."
              break
            fi
            if [ "$attempt" = "5" ]; then
              echo "Failed to push the version bump after $attempt attempts." >&2
              exit 1
            fi
            echo "Push rejected — rebasing on latest main and retrying (attempt $attempt)."
            git pull --rebase origin main
          done
      - name: Inject Cloudflare Web Analytics token
        # The beacon token is public (it ships in the client), so it lives in a
        # repo *variable*, not a secret. When set, substitute it into the served
        # analytics.js; when unset, the placeholder stays and analytics no-ops.
        # sed uses '#' as its delimiter so the line contains no shell pipe.
        env:
          CLOUDFLARE_ANALYTICS_TOKEN: ${{ vars.CLOUDFLARE_ANALYTICS_TOKEN }}
        run: |
          if [ -n "$CLOUDFLARE_ANALYTICS_TOKEN" ]; then
            sed -i "s#REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN#${CLOUDFLARE_ANALYTICS_TOKEN}#" site/assets/analytics.js
            echo "Injected Cloudflare Web Analytics token from the CLOUDFLARE_ANALYTICS_TOKEN variable."
          else
            echo "CLOUDFLARE_ANALYTICS_TOKEN variable not set — analytics stays off (placeholder retained)."
          fi
      - uses: actions/configure-pages@v5
        with:
          # First run enables Pages (source: GitHub Actions) if the token is
          # allowed to; otherwise enable it once in Settings → Pages.
          enablement: true
      - uses: actions/upload-pages-artifact@v4
        with:
          path: site
      - id: deployment
        uses: actions/deploy-pages@v4
----
name: CI
on:
  pull_request:
  push:
    branches: [main]
  # Dispatchable so baselining can start this run on the nightly maintenance PR.
  # That PR's branch push and its open both ride the Action's GITHUB_TOKEN, and
  # GitHub's recursion guard suppresses workflow runs for events that token
  # authors — so the PR gets no pull_request run at all, and `maintenance.delivery:
  # auto-merge` waits on a check that never appears. workflow_dispatch is the
  # guard's one documented exception, which is why baselining's deliver() starts
  # the checks itself.
  workflow_dispatch:
jobs:
  conformance:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 22
      - name: Claudinite world-scope conformance sweep
        run: node .claudinite/shared/engine/checks/check_the_world.mjs
      # The glob is explicit on purpose: bare `node --test` skips dot-directories,
      # so it would find none of these and still exit green (claudinite-website/node-test-discovery).
      - name: Local pack rule fixtures
        run: node --test '.claudinite/local/packs/**/*.test.mjs'
----
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../../shared/engine/checks/helpers/github-workflows.mjs';

// WHY. Node's default test discovery skips dot-directories outright, and every
// test this repo has lives under `.claudinite/`. So a `node --test` that names
// no path finds nothing, reports success, and reads exactly like a passing
// suite — the failure mode is a green tick over zero assertions, which no
// human and no CI log inspection reliably catches.
//
// The same silent-green also arrives one step later: an invocation that DOES
// name a path, but whose glob or directory matches no file in the tree (a typo,
// a moved fixture, a pack renamed). That is why this rule asserts the stronger
// property — the invocation's arguments must resolve to something that exists —
// rather than merely "an argument was passed". Watching the run go green is
// never the confirmation; a statically non-empty argument set is.
//
// SCOPE. The command surfaces a run can be spelled on: `package.json` scripts
// (the local invocation) and `.github/workflows/*.yml` (the CI step). A command
// carrying shell interpolation (`$…`, backticks) is not judged — its arguments
// are not knowable from the artifact, and a check that guesses cries wolf.

const SHARED_PREFIX = '.claudinite/shared/';

// A shell command's tokens, quotes stripped. Deliberately naive: the commands
// this rule reads are short literal invocations, and anything with substitution
// in it is skipped before we get here.
function tokenize(command) {
  return command.trim().split(/\s+/).filter(Boolean).map((t) => t.replace(/^['"]|['"]$/g, ''));
}

// Split a script body / run: line into individual commands on the shell's
// separators, so `npm ci && node --test` is judged as its two commands.
function commands(text) {
  return text.split(/\n|&&|\|\||[;|]/g);
}

// A glob token as a regex over '/'-separated repo paths: `**` crosses
// directories, `*` and `?` do not.
function globToRegExp(pattern) {
  let out = '';
  for (let i = 0; i < pattern.length; i += 1) {
    const c = pattern[i];
    if (c === '*') {
      if (pattern[i + 1] === '*') {
        // `**/` may match zero directories, so the following slash is optional.
        i += 1;
        if (pattern[i + 1] === '/') { i += 1; out += '(?:.*/)?'; } else out += '.*';
      } else out += '[^/]*';
    } else if (c === '?') out += '[^/]';
    else out += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${out}$`);
}

// Does this argument name at least one file that exists in the repo — as a
// glob, an exact path, or a directory holding files?
export function resolvesToFiles(arg, paths) {
  if (!arg) return false;
  if (/[*?[\]]/.test(arg)) {
    const re = globToRegExp(arg);
